"""Direct access to the engine's document model.

The engine runs inside this process. A one-line script, run by the engine
for each document once it's loaded, hands us that document's model; from
then on the full document API is a plain Python call away.
"""
import os
import sys

ENGINE_PROGRAM = "/usr/lib/libreoffice/program"
SCRIPT_URL = "vnd.sun.star.script:folio_bridge.py$attach?language=Python&location=user"

SCRIPT = '''# Generated by Folio Writer. Hands each document's model to the app.
def attach(*args):
    from folio import bridge
    bridge._attach(XSCRIPTCONTEXT)


g_exportedScripts = (attach,)
'''

_waiting = []
ctx = None


def install(profile):
    """Write the hand-off script into the engine profile."""
    d = os.path.join(profile, "user", "Scripts", "python")
    os.makedirs(d, exist_ok=True)
    fn = os.path.join(d, "folio_bridge.py")
    try:
        with open(fn, encoding="utf-8") as f:
            if f.read() == SCRIPT:
                return
    except OSError:
        pass
    with open(fn, "w", encoding="utf-8") as f:
        f.write(SCRIPT)


def prepare_path():
    if ENGINE_PROGRAM not in sys.path:
        sys.path.append(ENGINE_PROGRAM)
    here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    if here not in sys.path:
        sys.path.insert(0, here)


_attached = set()


def request(engine):
    """Find engine.view's document model.

    The first time, a one-line script run by the engine hands over the
    component context. After that the model is looked up directly from the
    UI thread. (Nothing from the engine's own thread ever calls back into
    Python afterwards: that could deadlock against UI-thread calls.)"""
    if ctx is not None:
        from gi.repository import GLib
        GLib.idle_add(_find, engine, 0)
        return
    _waiting.append(engine)
    engine.view.post_command(SCRIPT_URL, "{}", False)
    from gi.repository import GLib

    def retry(n=[0]):
        # the very first request can arrive before the engine is ready for it
        if engine.model is not None or engine not in _waiting:
            return False
        if ctx is not None:
            _waiting.remove(engine)
            _find(engine, 0)
            return False
        n[0] += 1
        if n[0] > 20:
            return False
        engine.view.post_command(SCRIPT_URL, "{}", False)
        return True
    GLib.timeout_add(1200, retry)


def _uid(model):
    try:
        return model.RuntimeUID
    except Exception:
        return id(model)


def _find(engine, tries):
    from .engine import file_url
    want = file_url(engine.opened_path) if getattr(engine, "opened_path", None) else None
    desktop = create("com.sun.star.frame.Desktop")
    found = None
    spare = None
    en = desktop.getComponents().createEnumeration()
    while en.hasMoreElements():
        c = en.nextElement()
        try:
            if not c.supportsService("com.sun.star.text.TextDocument"):
                continue
            if _uid(c) in _attached:
                continue
            url = c.getURL()
        except Exception:
            continue
        if want and url == want:
            found = c
            break
        if not url and spare is None:
            spare = c
    found = found or spare
    if found is None:
        if tries < 40:
            from gi.repository import GLib
            GLib.timeout_add(150, _find, engine, tries + 1)
        return False
    _attached.add(_uid(found))
    engine._set_model(found)
    return False


def _attach(xsc):
    global ctx
    ctx = xsc.getComponentContext()
    if ctx is None:
        import uno
        ctx = uno.getComponentContext()
    doc = xsc.getDocument()
    if _waiting:
        eng = _waiting.pop(0)
        _attached.add(_uid(doc))
        eng._set_model(doc)


def create(name, *args):
    smgr = ctx.getServiceManager()
    if args:
        return smgr.createInstanceWithArgumentsAndContext(name, args, ctx)
    return smgr.createInstanceWithContext(name, ctx)


class _Struct:
    """A UNO struct when LibreOffice isn't installed (Folio's own engine reads
    these as plain values)."""

    def __init__(self, typename, **kw):
        self.__dict__["typeName"] = typename
        self.__dict__.update(kw)

    def __getattr__(self, k):
        return 0

    def __eq__(self, o):
        return isinstance(o, _Struct) and o.__dict__ == self.__dict__

    def __repr__(self):
        return "<%s %r>" % (self.typeName, {k: v for k, v in self.__dict__.items() if k != "typeName"})


class _Enum:
    def __init__(self, typename, value):
        self.typeName, self.value = typename, value

    def __eq__(self, o):
        return getattr(o, "value", o) == self.value and getattr(o, "typeName", self.typeName) == self.typeName

    def __hash__(self):
        return hash((self.typeName, self.value))

    def __repr__(self):
        return "<Enum %s.%s>" % (self.typeName, self.value)


def struct(name, **kw):
    try:
        import uno
    except ImportError:
        return _Struct(name, **kw)
    s = uno.createUnoStruct(name)
    for k, v in kw.items():
        setattr(s, k, v)
    return s


def enum(typ, value):
    try:
        import uno
    except ImportError:
        return _Enum(typ, value)
    try:
        return uno.Enum(typ, value)
    except Exception:
        # a value the old engine doesn't have (Word's bar tab): Folio's own engine takes it
        return _Enum(typ, value)


def prop(name, value):
    return struct("com.sun.star.beans.PropertyValue", Name=name, Value=value)
